    }
  },
  {
    json: {
      name: "Paradox The Wrapper",
      category: "Vinyl Wrap & Craftsmanship",
      url: "https://www.youtube.com/@ParadoxTheWrapper/shorts"
    }
  },
  {
    json: {
      name: "EVS Motors",
      category: "Supercar Vinyl & PPF",
      url: "https://www.youtube.com/@evsmotors/shorts"
    }
  }
];

// Studio Shorts shelves in, new qualified posts out. Nothing is estimated here: the real date, views and likes
// come from the post page in the next step. This node reads only the title and the rounded shelf view count.
const existingRows = $("Google Sheets: Read Existing Post IDs").all();
const existingIds = new Set();
const existingUrls = new Set();
for (const row of existingRows) {
  if (row.json) {
    if (row.json.post_id) existingIds.add(String(row.json.post_id).trim());
    if (row.json.source_url) existingUrls.add(String(row.json.source_url).trim());
  }
}

const negativeRegex = /(window tint|tinted glass|ceramic coat|oil change|exhaust sound|turbo upgrade|engine swap|brake pad|dent repair|crash|car accident|mechanic review|transmission)/i;
const disasterRegex = /(ruined|destroyed|worst wrap|failed inspect|police stopped|lawsuit|scratching paint|blade slipped|nightmare)/i;
const wrapWhitelistRegex = /(wrap|vinyl|ppf|paint protection|squeegee|knifeless|peel|color change|fleet|livery|corner tuck|heat gun|decal|matte|satin|gloss|metallic|shield|film|rwb|build|diy|car|auto|color|transformation)/i;
const giveawayRegex = /(giveaway|win a free|tag 3 friends|enter to win|raffle|free wrap contest)/i;
const MAX_PER_CHANNEL = 8;

function decode(text) {
  try { return JSON.parse('"' + text + '"'); } catch (e) { return text; }
}
function shelfViews(acc) {
  const m = acc.match(/([0-9][0-9.,]*)\s*(thousand|million)?\s*views?\b/i);
  if (!m) return null;
  const num = parseFloat(m[1].replace(/,/g, ""));
  if (!Number.isFinite(num)) return null;
  const unit = (m[2] || "").toLowerCase();
  return Math.round(unit === "million" ? num * 1000000 : unit === "thousand" ? num * 1000 : num);
}

const channelGroups = new Map();
for (const input of $input.all()) {
  const rawText = input.json.data || input.json;
  if (!rawText || typeof rawText !== "string" || !rawText.includes("shortsLockupViewModel")) continue;
  const channelMatch = rawText.match(/<meta property="og:title" content="([^"]+)"/) || rawText.match(/<title>([^<]+)<\/title>/);
  const channelName = channelMatch ? decode(channelMatch[1].replace(" - YouTube", "").trim()) : "Wrap Studio";
  const shortsRegex = /"shortsLockupViewModel":\{[\s\S]*?"entityId":"shorts-shelf-item-([a-zA-Z0-9_-]{11})"[\s\S]*?"accessibilityText":"([^"]+)"/g;
  const entries = [];
  let match;
  while ((match = shortsRegex.exec(rawText)) !== null) {
    const acc = decode(match[2]);
    const views = shelfViews(acc);
    if (views === null) continue;
    const title = acc.replace(/,\s*[0-9][0-9.,]*\s*(thousand|million)?\s*views?\b.*$/i, "").trim();
    entries.push({
      postId: match[1],
      title,
      sourceUrl: `https://www.youtube.com/shorts/${match[1]}`,
      thumbUrl: `https://i.ytimg.com/vi/${match[1]}/hqdefault.jpg`,
      views
    });
  }
  if (entries.length > 0) channelGroups.set(channelName, entries);
}

const ingestedAt = new Date().toISOString();
const qualifiedItems = [];
const seenHashes = new Set();

for (const [channelName, entries] of channelGroups.entries()) {
  // Baseline: median shelf views of this studio's recent Shorts.
  const viewsList = entries.map(e => e.views).sort((a, b) => a - b);
  const baselineViews = viewsList[Math.floor(viewsList.length / 2)];
  let taken = 0;

  for (const entry of entries) {
    if (taken >= MAX_PER_CHANNEL) break;
    if (existingIds.has(entry.postId) || existingUrls.has(entry.sourceUrl)) continue;

    const headlineOnly = entry.title.replace(/#[a-zA-Z0-9_]+/g, "").trim();
    const contentHash = `${channelName}:${headlineOnly.toLowerCase().replace(/[^a-z0-9]/g, "")}`;
    if (seenHashes.has(contentHash)) continue;
    seenHashes.add(contentHash);

    if (negativeRegex.test(headlineOnly)) continue;
    if (disasterRegex.test(headlineOnly)) continue;
    if (!wrapWhitelistRegex.test(entry.title)) continue;
    if (giveawayRegex.test(entry.title)) continue;
    taken++;

    const titleLower = entry.title.toLowerCase();
    let wrapCategory = "Commercial Fleet";
    if (titleLower.includes("color") || titleLower.includes("gloss") || titleLower.includes("satin") || titleLower.includes("matte") || titleLower.includes("shift")) {
      wrapCategory = "Consumer Color Change";
    } else if (titleLower.includes("ppf") || titleLower.includes("protect")) {
      wrapCategory = "Paint Protection Film";
    } else if (titleLower.includes("hood") || titleLower.includes("roof") || titleLower.includes("partial")) {
      wrapCategory = "Partial Wrap";
    }

    qualifiedItems.push({
      post_id: entry.postId,
      platform: "YouTube Shorts",
      creator_handle: channelName,
      source_url: entry.sourceUrl,
      permanent_media_url: entry.thumbUrl,
      caption_text: entry.title,
      wrap_category: wrapCategory,
      baseline_views: baselineViews,
      ingested_at: ingestedAt
    });
  }
}

// No new posts: one marker item, so the IF node takes its failure branch instead of ending silently.
if (qualifiedItems.length === 0) return [{ json: { note: "no new qualified posts" } }];
return qualifiedItems.map(item => ({ json: item }));

// Joins each qualified post with its real page data, fetched here from the public Shorts page.
// A post with no usable date or view count is dropped, never estimated. Posts under 6 hours old are dropped (observation floor).
const helpers = this.helpers;
const MIN_AGE_HOURS = 6;
const CONCURRENCY = 6;
const UA = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36";
const posts = $input.all().map(i => i.json);
const nowMs = Date.now();

async function pageMeta(postId) {
  try {
    const html = await helpers.httpRequest({
      method: "GET",
      url: `https://www.youtube.com/shorts/${postId}`,
      headers: { "User-Agent": UA, "Accept-Language": "en-US,en;q=0.9" },
      timeout: 30000,
      json: false
    });
    const text = typeof html === "string" ? html : "";
    const date = text.match(/"publishDate":"([^"]+)"/);
    const views = text.match(/"viewCount":"(\d+)"/);
    const likes = text.match(/"likeCount":"?(\d+)/);
    if (!date || !views) return null;
    const published = new Date(date[1]);
    if (Number.isNaN(published.getTime())) return null;
    return { published_at: published.toISOString(), views: parseInt(views[1], 10), likes: likes ? parseInt(likes[1], 10) : null };
  } catch (e) {
    return null;
  }
}

const metas = [];
for (let i = 0; i < posts.length; i += CONCURRENCY) {
  metas.push(...await Promise.all(posts.slice(i, i + CONCURRENCY).map(p => pageMeta(p.post_id))));
}

const out = [];
let failed = 0;
let tooNew = 0;
posts.forEach((post, i) => {
  const meta = metas[i];
  if (!meta) { failed++; return; }
  const ageHours = (nowMs - new Date(meta.published_at).getTime()) / 3600000;
  if (!(ageHours >= MIN_AGE_HOURS)) { tooNew++; return; }
  out.push({
    json: {
      ...post,
      published_at: meta.published_at,
      views_count: meta.views,
      likes_count: meta.likes === null ? "" : meta.likes,
      comments_count: "",
      viral_velocity_per_hour: Math.round(meta.views / ageHours),
      outlier_multiplier: parseFloat((meta.views / Math.max(post.baseline_views, 100)).toFixed(2))
    }
  });
});

if (out.length === 0) {
  throw new Error(`Post page data unusable for all ${posts.length} posts (fetch or parse failed: ${failed}, under ${MIN_AGE_HOURS}h old: ${tooNew}). Check the YouTube page format and this server's access to youtube.com.`);
}
return out;

// One Gemini request per post. Gemini watches the first 15 seconds of the public Short (video and audio) at low
// frame resolution, so the tags come from what is on screen, not from the title. JSON schema output, temperature 0.
const ENUMS = {
  "market_segment": [
    "Commercial Fleet",
    "Consumer Color Change",
    "Paint Protection Film",
    "Partial Wrap"
  ],
  "visual_hook_archetype": [
    "The 3 Second Corner Tuck Macro Hook",
    "The Satisfying Hood Peel ASMR",
    "The Costly Installer Mistake Warning",
    "The Commercial Work Van Rolling Billboard",
    "The Liquid Gloss Sunlight Flake Pop",
    "No Clear Match"
  ],
  "visual_composition": [
    "Cinematic 360 Orbit",
    "Macro Extreme Close Up",
    "High Velocity Time Lapse Compression",
    "Split Screen Before and After"
  ],
  "audio_profile": [
    "Raw Shop Ambient ASMR Squeegee Sound",
    "Spoken Founder Educational Voiceover",
    "Trending Beat Drop Bass Sync"
  ],
  "offer_call_to_action": [
    "Direct Bio Quote Link",
    "Fleet Volume Pricing Tease",
    "Color Sample Swatch Request",
    "Local Metro Installation Booking"
  ],
  "replicability_tier": [
    "High Replicability",
    "Medium Replicability"
  ]
};
const FIELDS = Object.keys(ENUMS);

const properties = {};
for (const key of FIELDS) properties[key] = { type: "STRING", enum: ENUMS[key] };
properties.performance_thesis = { type: "STRING" };

const systemText = "You are an elite short form automotive creative director studying vehicle wrap Shorts. " +
  "You are given the first 15 seconds of one public Short, video and audio, plus its title and public numbers. " +
  "Classify only what you can see and hear. visual_hook_archetype describes the first 3 seconds: if none of the five patterns fits, use \"No Clear Match\". " +
  "audio_profile describes the sound you hear. performance_thesis is two sentences on why the opening may have held attention, " +
  "inferred from what is on screen and the numbers. Do not claim anything you cannot see or hear.";

// Reads the typed post rows from the merge step, so it does not depend on what the Sheets node returns.
return $("Code: Fetch Post Metadata And Merge").all().map(item => {
  const p = item.json;
  const userText = `Post ID: ${p.post_id}\nStudio: ${p.creator_handle}\nTitle: ${p.caption_text}\nPublished: ${p.published_at}\n` +
    `Views: ${p.views_count}\nLikes: ${p.likes_count}\nViews as a multiple of the studio median: ${p.outlier_multiplier}x\n\n` +
    "Classify the first 15 seconds of this Short.";
  return {
    json: {
      post_id: p.post_id,
      request: {
        systemInstruction: { parts: [{ text: systemText }] },
        contents: [{
          role: "user",
          parts: [
            { fileData: { fileUri: `https://www.youtube.com/watch?v=${p.post_id}` }, videoMetadata: { startOffset: "0s", endOffset: "15s" } },
            { text: userText }
          ]
        }],
        generationConfig: {
          temperature: 0,
          responseMimeType: "application/json",
          mediaResolution: "MEDIA_RESOLUTION_LOW",
          responseSchema: { type: "OBJECT", properties, required: [...FIELDS, "performance_thesis"] }
        }
      }
    }
  };
});

// Reads Gemini's JSON (from the video analysis call) for each post. No fallback tags and no default values: a post Gemini did not tag cleanly
// is left out of the patterns tab, and a run where Gemini fails for most posts stops with an error.
const ENUMS = {
  market_segment: ["Commercial Fleet", "Consumer Color Change", "Paint Protection Film", "Partial Wrap"],
  visual_hook_archetype: ["The 3 Second Corner Tuck Macro Hook", "The Satisfying Hood Peel ASMR", "The Costly Installer Mistake Warning", "The Commercial Work Van Rolling Billboard", "The Liquid Gloss Sunlight Flake Pop"] .concat(["No Clear Match"]),
  visual_composition: ["Cinematic 360 Orbit", "Macro Extreme Close Up", "High Velocity Time Lapse Compression", "Split Screen Before and After"],
  audio_profile: ["Raw Shop Ambient ASMR Squeegee Sound", "Spoken Founder Educational Voiceover", "Trending Beat Drop Bass Sync"],
  offer_call_to_action: ["Direct Bio Quote Link", "Fleet Volume Pricing Tease", "Color Sample Swatch Request", "Local Metro Installation Booking"],
  replicability_tier: ["High Replicability", "Medium Replicability"]
};
const MAX_FAILED_SHARE = 0.3;

const items = $input.all();
const rawItems = $("Code: Fetch Post Metadata And Merge").all();
const rows = [];
const failures = [];

for (let idx = 0; idx < items.length; idx++) {
  const raw = (rawItems[idx] && rawItems[idx].json) || {};
  const j = items[idx].json || {};
  let parsed = null;
  let why = "";

  if (j.error) {
    why = typeof j.error === "string" ? j.error : (j.error.message || "Gemini error");
  } else {
    const candidate = (j.candidates && j.candidates[0]) || {};
    const part = ((candidate.content && candidate.content.parts) || []).find(p => typeof p.text === "string");
    if (!part) {
      why = `no text in the Gemini response (finishReason ${candidate.finishReason || "none"})`;
    } else {
      try {
        parsed = JSON.parse(part.text.trim());
      } catch (e) {
        why = "Gemini returned invalid JSON";
      }
    }
  }

  if (parsed) {
    for (const key of Object.keys(ENUMS)) {
      if (!ENUMS[key].includes(parsed[key])) { why = `unexpected value for ${key}`; parsed = null; break; }
    }
  }
  if (parsed && (typeof parsed.performance_thesis !== "string" || parsed.performance_thesis.trim().length < 20)) {
    why = "performance_thesis missing"; parsed = null;
  }
  if (!parsed) { failures.push(`${raw.post_id || "post " + idx}: ${why}`); continue; }

  rows.push({
    json: {
      post_id: raw.post_id,
      creator_handle: raw.creator_handle || "",
      source_url: raw.source_url || "",
      views_count: raw.views_count,
      likes_count: raw.likes_count,
      ingested_at: raw.ingested_at,
      market_segment: parsed.market_segment,
      visual_hook_archetype: parsed.visual_hook_archetype,
      visual_composition: parsed.visual_composition,
      audio_profile: parsed.audio_profile,
      offer_call_to_action: parsed.offer_call_to_action,
      performance_thesis: parsed.performance_thesis.trim(),
      replicability_tier: parsed.replicability_tier
    }
  });
}

if (rows.length === 0 || failures.length / Math.max(items.length, 1) > MAX_FAILED_SHARE) {
  throw new Error(`Gemini tagging failed for ${failures.length} of ${items.length} posts. First: ${failures.slice(0, 3).join(" | ")}`);
}
return rows;

// Top patterns from this run's tagged posts. Lift is the median of each post's views divided by its studio's
// median views, minus 1. Patterns with fewer than MIN_N posts stay in the table but rank below the rest and are
// labelled low sample. Patterns with no posts are not listed. The shot, audio and copy text is a fixed creative
// template per pattern: only the lift, the post count and the post_ids come from the data.
const MIN_N = 3;
const playbooks = {
  "The 3 Second Corner Tuck Macro Hook": {
    "target": "Commercial Fleet and Master Restylers",
    "shot1": "Macro extreme close up of heat gun stretching vinyl over compound curved door handle (0 to 3s)",
    "shot2": "Snap cut to seamless corner tuck without relief cut wrinkle (3 to 6s)",
    "shot3": "Steadicam pull back revealing full vehicle livery under fluorescent bay lighting (6 to 12s)",
    "audio": "Raw shop heat gun hiss into sharp vinyl squeak, followed by heavy bass drop reveal",
    "copy": "No wrinkles, no excuses. Commercial fleet wraps built for daily work. Link in bio for fleet quotes."
  },
  "The Satisfying Hood Peel ASMR": {
    "target": "B2C Color Change Enthusiasts",
    "shot1": "Single continuous hand pull removing clear protective cap from ultra gloss vinyl (0 to 3s)",
    "shot2": "Camera pans alongside vinyl peel reflecting studio tube lights (3 to 7s)",
    "shot3": "Low angle optical glare shot capturing deep metallic flake in sunlight (7 to 15s)",
    "audio": "Microphone glued to vinyl edge for pure crisp ASMR peel acoustic, zero music",
    "copy": "Satisfying from every angle. Comment your dream car color below. Message us to book a slot."
  },
  "The Costly Installer Mistake Warning": {
    "target": "Trade Business Owners and Quality Seekers",
    "shot1": "Red grease pencil circling a peeling edge on a competitor wrap with bold text: Never Do This (0 to 2s)",
    "shot2": "Side by side split screen showing failed dry application vs proper wet knifeless tape method (2 to 7s)",
    "shot3": "Finished panel flush cut with zero exposed factory paint (7 to 14s)",
    "audio": "Direct spoken voiceover with confident technical authority and subtle background beat",
    "copy": "Why edges lift when prep is rushed. DM us for a consultation."
  },
  "The Commercial Work Van Rolling Billboard": {
    "target": "B2B Commercial Contractors (Plumbing, HVAC, Electrical)",
    "shot1": "Beat up, faded white work van rolling into the dark garage bay (0 to 3s)",
    "shot2": "High speed 15x time lapse showing two technicians applying full branded commercial wrap (3 to 8s)",
    "shot3": "Bright daylight delivery shot with oversized phone number and QR code clearly legible from 50 feet (8 to 15s)",
    "audio": "High tempo upbeat electronic track with quick transition swooshes",
    "copy": "Turn your work van into a rolling billboard. Request pricing today."
  },
  "The Liquid Gloss Sunlight Flake Pop": {
    "target": "Exotic and Luxury Vehicle Owners",
    "shot1": "Wheel rolling in slow motion, sun hits the front fender causing an instant color flip (0 to 3s)",
    "shot2": "Low gimbal orbit around front bumper showing laser cut emblem insets (3 to 8s)",
    "shot3": "Full 360 drone orbit at golden hour capturing liquid gloss depth (8 to 15s)",
    "audio": "Ambient cinematic deep synth with subtle exhaust note overlay",
    "copy": "Paint protection and color change done right. DM for package details."
  }
};

const analyzed = $("Code: Parse Gemini Pattern Output").all().map(i => i.json);
const rawMap = new Map($("Code: Fetch Post Metadata And Merge").all().map(i => [i.json.post_id, i.json]));
const groups = new Map(Object.keys(playbooks).map(name => [name, []]));

for (const p of analyzed) {
  const raw = rawMap.get(p.post_id);
  const multiplier = raw ? parseFloat(raw.outlier_multiplier) : NaN;
  if (groups.has(p.visual_hook_archetype) && Number.isFinite(multiplier)) groups.get(p.visual_hook_archetype).push({ multiplier, post_id: p.post_id });
}

function median(values) {
  const s = [...values].sort((a, b) => a - b);
  const k = Math.floor(s.length / 2);
  return s.length % 2 ? s[k] : (s[k - 1] + s[k]) / 2;
}

const ranked = [...groups.entries()]
  .filter(([, entries]) => entries.length > 0)
  .map(([name, entries]) => ({ name, n: entries.length, lift: Math.round((median(entries.map(e => e.multiplier)) - 1) * 100), ids: entries.map(e => e.post_id).join(", ") }))
  .sort((a, b) => (b.n >= MIN_N) - (a.n >= MIN_N) || b.lift - a.lift || b.n - a.n)
  .slice(0, 5);

if (ranked.length === 0) throw new Error("No tagged post matched a known pattern, so there is nothing to summarize.");

return ranked.map((r, i) => {
  const t = playbooks[r.name];
  const direction = r.lift >= 0 ? `${r.lift}% above` : `${Math.abs(r.lift)}% below`;
  const lowSample = r.n >= MIN_N ? "" : ", low sample";
  return {
    json: {
      rank: i + 1,
      pattern_name: r.name,
      target_audience: t.target,
      average_outlier_lift: `${direction} studio median views (median of ${r.n} posts${lowSample})`,
      sample_count: r.n,
      post_ids: r.ids,
      shot_1_hook: t.shot1,
      shot_2_transition: t.shot2,
      shot_3_reveal: t.shot3,
      audio_direction: t.audio,
      copy_cta_template: t.copy
    }
  };
});

const err = $json.execution?.error || {};
return [
  {
    json: {
      alert_status: "CRITICAL_PIPELINE_FAILURE",
      failed_at: new Date().toISOString(),
      workflow_name: $json.workflow?.name,
      failing_node: err.node?.name || "Unknown Node",
      error_message: err.message || "Unhandled exception in execution",
      stack_summary: err.stack ? err.stack.slice(0, 300) : "No stack trace"
    }
  }
];
